import {weekDays,dailyItems,planningTotals} from './lastplanner-planning-model.mjs';
export const PLANNING_VIEWS=[['tarjetas','Tarjetas','Revisa y gestiona las actividades de cada día'],['kanban','Kanban','Organiza y mueve trabajos entre días'],['cronograma','Cronograma','Visualiza la duración y continuidad de las actividades']];
export function plannerMarkup({state,rows,restrictions,esc}){
 if(!state.planningMode)return `<section class="lpPlanChooser"><small>ATLAS HPC · PLANIFICACIÓN</small><h2>¿Cómo quieres visualizar tu planificación?</h2><p>Selecciona una vista para comenzar.</p><div role="radiogroup" aria-label="Vista de planificación">${PLANNING_VIEWS.map(([id,name,desc])=>`<button type="button" role="radio" aria-checked="${state.pickMode===id}" data-plan-choice="${id}"><div class="lpPlanPreview ${id}" aria-hidden="true">${Array.from({length:7},(_,i)=>`<i style="--i:${i}"><b></b><b></b></i>`).join('')}</div><span><strong>${name}</strong><small>${desc}</small></span><em aria-hidden="true">${state.pickMode===id?'●':'○'}</em></button>`).join('')}</div><button type="button" class="primary" data-plan-enter>Ingresar a ${PLANNING_VIEWS.find(v=>v[0]===state.pickMode)[1]}</button></section>`;
 const days=weekDays(state.day),totals=planningTotals(rows),status=a=>a.fase==='borrador'?'Borrador':a.verificacion.resultado==='Pendiente de verificación'?a.estado:a.verificacion.resultado;
 const card=({activity:a,date,assignments})=>`<article class="lpPlanTask" data-planning-activity="${esc(a.id)}">${state.planningMode==='kanban'&&a.fase==='borrador'?`<button type="button" class="lpPlanDragHandle" draggable="true" data-drag-activity="${esc(a.id)}" data-drag-date="${date}" aria-label="Arrastrar jornada de ${esc(a.actividad)}">⠿ Mover jornada</button>`:''}<button type="button" data-plan-detail="${esc(a.id)}" data-date="${date}"><b>${esc(a.actividad)}</b>${a.planificacion?.apu?`<small>APU ${esc(a.planificacion.apu.code)} · ${esc(a.planificacion.apu.operation?.label||a.planificacion.apu.description)}</small>`:''}<small>${esc(a.level)} · ${a.recintos.length} recintos · ${a.alcances.filter(s=>!s.locationOnly).length} superficies</small><small>${a.cantidad} ${esc(a.unidad)} totales de la actividad</small><span>${assignments.length?assignments.map(r=>esc(r.teamName)+' · '+r.people+' pers.').join(' / '):(state.team||state.contratista?'Sin personal del filtro':'Sin personal programado')}</span><small>${esc(a.contratista)} · ${esc(status(a))}</small>${restrictions.some(r=>a.restrictionIds.includes(r.id)&&!['Liberada','Cerrada'].includes(r.estado))?'<small class="lpPlanBlock">Restricción pendiente</small>':''}</button><div><button type="button" data-plan-location="${esc(a.id)}">Ubicación</button><button type="button" data-plan-quick="${esc(a.id)}" data-date="${date}">Editar jornada</button></div></article>`;
 const dayTitle=(d,i)=>`${['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'][i]} ${Number(d.slice(-2))}`;
 let content;
 if(state.planningMode==='cronograma')content=`<div class="lpGanttScroll"><table class="lpGantt"><caption>Período planificado y jornadas con personal · sin inferir avance ejecutado</caption><thead><tr><th>Actividad</th>${days.map((d,i)=>`<th>${dayTitle(d,i)}</th>`).join('')}</tr></thead><tbody>${rows.map(a=>`<tr data-planning-activity="${esc(a.id)}"><th><button type="button" data-plan-detail="${esc(a.id)}" data-date="${days[0]}">${esc(a.actividad)}</button><small>${a.cantidad} ${esc(a.unidad)} totales</small></th>${days.map(d=>{const item=dailyItems([a],d,state)[0],people=item?.assignments.reduce((n,r)=>n+r.people,0)||0;return `<td class="${item?'lpGanttPeriod':''} ${people?'lpGanttStaff':''}">${item?`<button type="button" data-plan-quick="${esc(a.id)}" data-date="${d}">${people?people+' pers.':'Sin personal'}</button>`:'—'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`;
 else content=`<div class="${state.planningMode==='kanban'?'lpKanban':'lpDayCards'}">${days.map((d,i)=>{const items=dailyItems(rows,d,state);return `<section class="lpPlanDay" data-drop-date="${d}"><header><h3>${dayTitle(d,i)}</h3><button type="button" data-plan-new="${d}" aria-label="Agregar actividad el ${dayTitle(d,i)}">+ Agregar actividad</button></header>${items.map(card).join('')||'<p>Sin actividades.</p>'}</section>`;}).join('')}</div>`;
 return `<section class="lpPlanningBoard"><div class="lpPlanHeading"><div><small>ATLAS HPC · PLANIFICACIÓN</small><h2>${PLANNING_VIEWS.find(v=>v[0]===state.planningMode)[1]} · Plan semanal</h2><p>${totals.activities} actividades únicas · ${totals.quantities.map(v=>v.quantity+' '+esc(v.unit)).join(' / ')||'Sin compromisos'}</p></div><div><button type="button" data-plan-new="${state.day}">+ Nueva actividad</button><button type="button" data-plan-change>Cambiar vista</button></div></div>${state.undo?'<button type="button" data-plan-undo>Deshacer último cambio de programación</button>':''}${content}<p class="lpCycleNote">Una actividad mostrada en varios días conserva un único compromiso total.</p></section>`;
}
export function bindPlanner(root,actions){let lastDragAt=0;root.querySelectorAll('[data-plan-choice]').forEach(b=>b.onclick=()=>actions.choose(b.dataset.planChoice));root.querySelector('[data-plan-enter]')?.addEventListener('click',actions.enter);root.querySelector('[data-plan-change]')?.addEventListener('click',actions.change);root.querySelector('[data-plan-undo]')?.addEventListener('click',actions.undo);for(const [key,fn] of [['new','create'],['detail','detail'],['quick','quick'],['location','location']])root.querySelectorAll('[data-plan-'+key+']').forEach(b=>b.onclick=e=>{if(Date.now()-lastDragAt<400){e.preventDefault();return;}actions[fn](b.dataset['plan'+key[0].toUpperCase()+key.slice(1)],b.dataset.date);});let dragged=null;root.querySelectorAll('[data-drag-activity]').forEach(el=>{el.onclick=e=>{if(Date.now()-lastDragAt<400){e.preventDefault();return;}actions.move(el.dataset.dragActivity,el.dataset.dragDate,el.dataset.dragDate);};el.ondragstart=e=>{lastDragAt=Date.now();dragged={id:el.dataset.dragActivity,date:el.dataset.dragDate};e.dataTransfer.setData('text/plain',JSON.stringify(dragged));};el.ondragend=()=>{lastDragAt=Date.now();dragged=null;root.querySelectorAll('[data-drag-over]').forEach(n=>n.removeAttribute('data-drag-over'));};});root.querySelectorAll('[data-drop-date]').forEach(el=>{el.ondragover=e=>{if(dragged){e.preventDefault();el.dataset.dragOver='true';}};el.ondragleave=e=>{if(!el.contains(e.relatedTarget))el.removeAttribute('data-drag-over');};el.ondrop=e=>{e.preventDefault();lastDragAt=Date.now();el.removeAttribute('data-drag-over');if(dragged)actions.move(dragged.id,dragged.date,el.dataset.dropDate);};});}
